package org.pexserver.pac.check.bedrock.prediction;

import org.pexserver.pac.check.core.BedrockViolationCheck;
import org.pexserver.pac.check.core.BedrockViolationContext;
import org.pexserver.pac.check.core.AbstractCheck;

/** PAC registry entry for violations generated by the Geyser-side physics engine. */
public final class BedrockPredictionCheck extends AbstractCheck implements BedrockViolationCheck {
    @Override public String key() { return "bedrock-prediction"; }
    // Bedrock prediction violations use the same configurable ban policy as other checks.
    @Override public boolean automaticKickEligible() { return false; }
    @Override public void inspect(BedrockViolationContext context) {
        flagLimited(context.uuid(), () -> context.flag(this));
    }
}
